const svg = (body, view = '0 0 140 126', cls = '') => `<svg class="${cls}" viewBox="${view}" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">${body}</svg>`;
export function icon(name, cls = '') {
  const parts = {
    drop: '<path d="M12 2C10 6 4 11 4 16a8 8 0 0016 0c0-5-6-10-8-14Z" fill="currentColor"/><path d="M8 15c-1 3 1 5 3 5" stroke="white" stroke-width="1.5" stroke-linecap="round"/>',
    leaf: '<path d="M20 3C9 2 2 8 5 16c3 7 15 2 15-13Z" fill="currentColor"/><path d="m3 22 12-13" stroke="#FBF8EC" stroke-width="1.7" stroke-linecap="round"/>',
    sun: '<circle cx="12" cy="12" r="4" fill="currentColor"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/>',
    arrow: '<path d="M4 12h15m-6-6 6 6-6 6" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>',
    check: '<path d="m5 12 4 4L20 5" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>',
    plus: '<path d="M12 5v14M5 12h14" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/>',
    close: '<path d="m6 6 12 12M6 18 18 6" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/>',
    seed: '<path d="M18 4C8 3 2 10 7 17c6 6 14-1 11-13Z" fill="currentColor"/><path d="m7 18 8-10" stroke="#fff9e9" stroke-width="1.5" stroke-linecap="round"/>',
    wheel: '<circle cx="12" cy="12" r="9" stroke="currentColor" stroke-width="1.8"/><circle cx="12" cy="12" r="2" fill="currentColor"/><path d="M12 3v7m9 2h-7m-2 9v-7M3 12h7M6 6l4 4m8-4-4 4m4 8-4-4M6 18l4-4" stroke="currentColor" stroke-width="1.2"/>',
    lock: '<rect x="5" y="10" width="14" height="11" rx="3" fill="currentColor"/><path d="M8 10V7a4 4 0 018 0v3" stroke="currentColor" stroke-width="2"/><path d="M12 14v3" stroke="#fff9e9" stroke-width="2" stroke-linecap="round"/>',
    volume: '<path d="M3 9h4l5-4v14l-5-4H3V9Z" fill="currentColor"/><path d="M16 8a6 6 0 010 8m3-11a10 10 0 010 14" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/>',
    undo: '<path d="M5 9h9a6 6 0 010 12M5 9l5-5M5 9l5 5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>',
  };
  return svg(parts[name] || parts.leaf, '0 0 24 24', `icon ${cls}`);
}

export function cropArt(type, stage = 3, variant = 0) {
  const base = '<ellipse cx="70" cy="111" rx="36" ry="8" fill="#284D37" opacity=".12"/>';
  if (stage === 0) return svg(base + '<path d="M70 107V89" stroke="#3E6441" stroke-width="5" stroke-linecap="round"/><path d="M69 99c-20 3-22-15-22-15s20-4 22 15Z" fill="#73A96F"/><path d="M72 94c17 0 21-15 21-15s-20-1-21 15Z" fill="#477A50"/><path d="m57 106 7-2m15 2 7 2" stroke="#A57C4E" stroke-width="2" stroke-linecap="round"/>');
  if (type === 'carrot') {
    const root = stage === 1 ? '<path d="M61 92q9-7 18 0l-7 18q-2 5-4 0Z" fill="#D99B63"/>' : '<path d="M54 68q16-12 33 0l-13 40q-4 9-8 0Z" fill="#E3924C"/><path d="M60 67q8-7 17-3l-9 43Z" fill="#EFA968"/><path d="m61 79 10 2m-6 8 9 2m-7 8 6 1" stroke="#BE753F" stroke-width="2" stroke-linecap="round"/>';
    const crown = stage === 1 ? '<path d="M70 93V65m0 17L54 65m16 14 15-19" stroke="#4F814F" stroke-width="4" stroke-linecap="round"/><path d="M70 74c-14 4-21-10-21-10s17-7 21 10Zm2-5c14 1 19-13 19-13S74 54 72 69Z" fill="#81A969"/>' : '<path d="m70 69-1-34m0 25L49 36m21 24 20-29" stroke="#4E7B49" stroke-width="4" stroke-linecap="round"/><path d="M69 48C50 48 48 27 48 27s22 4 21 21Z" fill="#7FA76A"/><path d="M70 41C56 26 66 13 66 13s15 12 4 28Z" fill="#5F9357"/><path d="M73 49c0-22 23-28 23-28S98 43 73 49Z" fill="#88AE72"/><path d="M66 58c-20 3-30-11-30-11s20-6 30 11Z" fill="#699B5C"/><path d="M75 59c18 1 29-15 29-15s-22-4-29 15Z" fill="#5C8750"/>';
    return svg(base + root + crown + (stage === 3 ? '<path d="m30 79 2-5 2 5 5 2-5 2-2 5-2-5-5-2 5-2Z" fill="#DBB75C"/>' : ''));
  }
  if (type === 'broccoli') {
    const stem = '<path d="m63 109 3-37h10l5 37" fill="#98B473"/><path d="m69 86-17-18m20 18 18-20" stroke="#8FAA6D" stroke-width="8" stroke-linecap="round"/><path d="M64 104C44 102 40 87 40 87s18-1 24 17Zm15-4c20-2 23-19 23-19s-20 2-23 19Z" fill="#6E995F"/>';
    const small = '<circle cx="71" cy="67" r="19" fill="#62915A"/><circle cx="58" cy="72" r="14" fill="#78A167"/><circle cx="84" cy="73" r="14" fill="#4F8054"/>';
    const head = '<path d="M35 68C22 55 33 37 49 41c1-21 27-27 39-11 18-6 34 12 24 28 9 17-11 33-24 22-17 10-29 7-38-1-8 3-15-1-15-11Z" fill="#487B50"/><circle cx="45" cy="54" r="15" fill="#6B995F"/><circle cx="65" cy="43" r="19" fill="#79A56A"/><circle cx="86" cy="47" r="18" fill="#568952"/><circle cx="98" cy="62" r="13" fill="#66965A"/><circle cx="67" cy="66" r="18" fill="#65975C"/><g fill="#8DB576" opacity=".8"><circle cx="58" cy="38" r="3"/><circle cx="68" cy="34" r="2.5"/><circle cx="42" cy="49" r="2.7"/><circle cx="78" cy="61" r="2.5"/><circle cx="89" cy="43" r="2.8"/></g>';
    return svg(base + stem + (stage === 1 ? small : head) + (stage === 3 ? '<path d="m110 92 2-5 2 5 5 2-5 2-2 5-2-5-5-2 5-2Z" fill="#DAB65C"/>' : ''));
  }
  const petals = Array.from({length:10},(_,i)=>`<ellipse cx="72" cy="27" rx="8" ry="17" fill="${i%2?'#F2CB63':'#E6B951'}" transform="rotate(${i*36} 72 48)"/>`).join('');
  return svg(base + '<path d="M71 109V51" stroke="#44754B" stroke-width="5" stroke-linecap="round"/><path d="M70 91c-25 2-30-19-30-19s24-3 30 19Z" fill="#79A46A"/><path d="M73 80c24 1 28-17 28-17S77 60 73 80Z" fill="#568954"/>' + (stage===1?'<ellipse cx="72" cy="56" rx="12" ry="17" fill="#88A35F"/><path d="m65 64 8-17 7 16" stroke="#54734B" stroke-width="2"/>':petals + '<circle cx="72" cy="48" r="16" fill="#7F532E"/><circle cx="72" cy="48" r="11" fill="#9C6E38"/><g fill="#E2AF5E"><ellipse cx="67" cy="43" rx="1.7" ry="2.7"/><ellipse cx="76" cy="42" rx="1.7" ry="2.7"/><ellipse cx="72" cy="50" rx="1.7" ry="2.7"/><ellipse cx="64" cy="51" rx="1.7" ry="2.7"/><ellipse cx="78" cy="52" rx="1.7" ry="2.7"/></g>') + (stage===3?'<path d="m108 37 2-5 2 5 5 2-5 2-2 5-2-5-5-2 5-2Z" fill="#E9BD54"/>':''));
}

export function wheelArt(running = false) {
  return svg(`<ellipse cx="150" cy="162" rx="112" ry="12" fill="#2B5B43" opacity=".1"/><path d="m63 154 22-90m91 90-19-90" stroke="#BC9270" stroke-width="8" stroke-linecap="round"/><g class="${running?'turning-wheel':''}" style="transform-origin:120px 78px"><circle cx="120" cy="78" r="66" fill="#E6EBD9" stroke="#9EB39A" stroke-width="9"/><circle cx="120" cy="78" r="53" stroke="#BCCCB0" stroke-width="2"/>${Array.from({length:12},(_,i)=>`<path d="M120 18v53" stroke="#B4C4A7" stroke-width="3" transform="rotate(${i*30} 120 78)"/>`).join('')}<circle cx="120" cy="78" r="9" fill="#6D8E6D"/></g><path d="M82 124c-10-31 12-54 40-49 30 6 43 32 25 47-11 10-52 14-65 2Z" fill="#C79B72"/><ellipse cx="112" cy="109" rx="32" ry="25" fill="#E9CBA5"/><ellipse cx="96" cy="82" rx="13" ry="16" fill="#C79B72"/><ellipse cx="96" cy="84" rx="7" ry="10" fill="#E6B0A0"/><ellipse cx="129" cy="83" rx="13" ry="15" fill="#C79B72"/><ellipse cx="129" cy="84" rx="7" ry="9" fill="#E6B0A0"/><ellipse cx="113" cy="112" rx="21" ry="18" fill="#F4E4CB"/><path d="m98 105 5 0m19 0 5 0" stroke="#423E30" stroke-width="3" stroke-linecap="round"/><path d="m110 112 3 2 3-2" stroke="#946958" stroke-width="2" stroke-linecap="round"/><path d="m153 155 8-14 10 13m11 2 10-24 10 23" stroke="#7FA176" stroke-width="5" stroke-linecap="round"/><path d="m207 147 10-19 10 20" stroke="#9FB38B" stroke-width="5" stroke-linecap="round"/><circle cx="222" cy="114" r="5" fill="#E7B95A"/>`, '0 0 270 180', 'wheel-illustration');
}

export function buildingArt(kind, built = false) {
  const muted = built ? '#E1C57C' : '#C4C7B2';
  if (kind === 'mill') return svg(`<path d="M28 103V53l35-26 35 26v50" fill="${built?'#E7D6B6':'#D7D8C8'}" stroke="#6F856C" stroke-width="3"/><path d="m21 56 42-34 43 34" stroke="#7B976F" stroke-width="9" stroke-linecap="round"/><path d="M57 104V75h18v29" fill="#A9BC98"/><circle cx="94" cy="87" r="24" fill="#B79D71" stroke="#6F7D59" stroke-width="4"/>${Array.from({length:8},(_,i)=>`<path d="M94 63v48" stroke="#E8D4A7" stroke-width="3" transform="rotate(${i*22.5} 94 87)"/>`).join('')}<circle cx="94" cy="87" r="6" fill="#6F7D59"/><path d="M9 112h122" stroke="#A8BC9B" stroke-width="4" stroke-linecap="round"/>`);
  if (kind === 'library') return svg(`<path d="M30 107V55l39-28 39 28v52" fill="${built?'#E8DBC0':'#D7D8C8'}" stroke="#7D8B6B" stroke-width="3"/><path d="m23 58 46-35 46 35" stroke="#8BA17C" stroke-width="10" stroke-linecap="round"/><rect x="45" y="68" width="49" height="35" rx="3" fill="#6D8768"/><path d="M51 77h36M51 91h36" stroke="#DBD8B2" stroke-width="2"/><g fill="${muted}"><rect x="53" y="66" width="6" height="10" rx="1"/><rect x="62" y="65" width="7" height="11" rx="1"/><rect x="73" y="68" width="6" height="8" rx="1"/><rect x="54" y="81" width="7" height="9" rx="1"/><rect x="66" y="82" width="5" height="8" rx="1"/><rect x="76" y="79" width="6" height="11" rx="1"/></g><path d="M16 112h108" stroke="#A8BC9B" stroke-width="4" stroke-linecap="round"/>`);
  return svg(`<path d="m48 110 7-62h30l8 62" fill="${built?'#E5CCA2':'#D7D8C8'}" stroke="#879371" stroke-width="3"/><path d="M48 49h45l-9-14H58l-10 14Z" fill="#628267"/><path d="M56 35V17h29v18" fill="${muted}" stroke="#7D8B6B" stroke-width="3"/><path d="m52 17 18-12 19 12" fill="#6D8F6D"/><path d="M70 22v8M63 27h14" stroke="#FFF7D5" stroke-width="2"/><path d="M64 110V93h14v17" fill="#9AAB88"/><path d="M36 114h71" stroke="#A8BC9B" stroke-width="4" stroke-linecap="round"/>${built?'<g stroke="#E3B854" stroke-width="2" stroke-linecap="round"><path d="M31 26h10m59 0h10M40 3l7 7m46 0 7-7"/></g>':''}`);
}
